import test from "node:test";
import assert from "node:assert/strict";

import { parseMarkdown, parseInline, splitTableRow, summarizeBlocks } from "../lib/markdown.js";
import { blocksToMarkdown, buildDocx, decodeXml, escapeXml, readDocx } from "../lib/docx.js";
import { readZip, writeZip } from "../lib/zip.js";

test("parses headings, lists, tables, quotes and code", () => {
	const blocks = parseMarkdown([
		"# 标题",
		"",
		"第一段 **粗体** 和 *斜体* 和 `code`。",
		"",
		"- 一",
		"- 二",
		"",
		"1. 甲",
		"2. 乙",
		"",
		"| 列A | 列B |",
		"| --- | --- |",
		"| 1 | 2 |",
		"",
		"> 引用",
		"",
		"```",
		"const x = 1;",
		"```"
	].join("\n"));
	assert.deepEqual(blocks.map((block) => block.type), [
		"heading", "paragraph", "bullet", "bullet", "numbered", "numbered",
		"table", "paragraph", "code"
	]);
	assert.equal(blocks[0].level, 1);
	assert.equal(blocks[6].rows.length, 2);
	assert.equal(blocks[6].rows[1][1], "2");
	assert.equal(blocks[7].quote, true);
	assert.deepEqual(blocks[8].lines, ["const x = 1;"]);
});

test("parses inline emphasis and leaves unmatched markers alone", () => {
	const runs = parseInline("a **b** *c* `d` and 2*3*4 and **open");
	const text = runs.map((run) => run.text).join("");
	assert.equal(text, "a b c d and 2*3*4 and **open");
	assert.equal(runs.find((run) => run.text === "b").bold, true);
	assert.equal(runs.find((run) => run.text === "c").italic, true);
	assert.equal(runs.find((run) => run.text === "d").code, true);
});

test("splits table cells on unescaped pipes", () => {
	assert.deepEqual(splitTableRow("| a | b\\|c | d |"), ["a", "b|c", "d"]);
	assert.deepEqual(splitTableRow("a|b"), ["a", "b"]);
});

test("escapes and decodes XML entities", () => {
	const text = `A & B < C > D "E" 'F' 中文`;
	assert.equal(decodeXml(escapeXml(text)), text);
	assert.equal(decodeXml("&#x4e2d;&#25991;"), "中文");
});

test("builds a docx whose parts are all present", () => {
	const { buffer, stats } = buildDocx("# 标题\n\n正文\n\n| a | b |\n| --- | --- |\n| 1 | 2 |\n");
	const archive = readZip(buffer);
	assert.deepEqual(archive.names().sort(), [
		"[Content_Types].xml",
		"_rels/.rels",
		"word/_rels/document.xml.rels",
		"word/document.xml",
		"word/numbering.xml",
		"word/styles.xml"
	]);
	assert.equal(stats.headings, 1);
	assert.equal(stats.tables, 1);
	const document = archive.text("word/document.xml");
	assert.match(document, /<w:body>/);
	assert.match(document, /<w:tbl>/);
	assert.match(document, /Heading1/);
});

test("round-trips a document through build and read", () => {
	const markdown = [
		"# 项目周报",
		"",
		"本周完成了 **Office 端侧** 的第一版，包含 `docx` 与 `xlsx`。",
		"",
		"## 进展",
		"",
		"- 纯 JS ZIP 读写",
		"- Word / Excel 生成",
		"",
		"1. 先写测试",
		"2. 再写实现",
		"",
		"| 模块 | 状态 |",
		"| --- | --- |",
		"| docx | 完成 |",
		"| xlsx | 进行中 |",
		"",
		"> 所有数据留在本机。",
		"",
		"```",
		"const x = 1;",
		"```",
		""
	].join("\n");
	const { buffer } = buildDocx(markdown);
	const { text, blocks, truncated } = readDocx(buffer);
	assert.equal(truncated, false);
	assert.match(text, /# 项目周报/);
	assert.match(text, /\*\*Office 端侧\*\*/);
	assert.match(text, /- 纯 JS ZIP 读写/);
	assert.match(text, /\| 模块 \| 状态 \|/);
	assert.match(text, /> 所有数据留在本机。/);
	assert.match(text, /const x = 1;/);
	const table = blocks.find((block) => block.type === "table");
	assert.deepEqual(table.rows, [["模块", "状态"], ["docx", "完成"], ["xlsx", "进行中"]]);
});

test("caps the returned text at maxChars", () => {
	const { buffer } = buildDocx("# 标题\n\n" + "很长的一段话。".repeat(500));
	const result = readDocx(buffer, { maxChars: 100 });
	assert.equal(result.truncated, true);
	assert.ok(result.text.length <= 100);
});

test("rejects a zip that is not a docx", () => {
	const buffer = writeZip([{ name: "word/other.xml", data: "<x/>" }]);
	assert.throws(() => readDocx(buffer), (error) => error.code === "OFFICE_BAD_ZIP");
});

test("blocksToMarkdown keeps the table readable", () => {
	const { blocks } = buildDocx("| a | b |\n| --- | --- |\n| 1 | 2 |\n");
	assert.match(blocksToMarkdown(blocks), /\| a \| b \|/);
});

test("summary counts every block type", () => {
	const stats = summarizeBlocks(parseMarkdown("# h\n\np\n\n- b\n\n1. n\n\n| a |\n| --- |\n| 1 |\n"));
	assert.deepEqual(stats, { paragraphs: 1, tables: 1, headings: 1, lists: 2 });
});
